ALTER TABLE public.staff_permissions ADD CONSTRAINT staff_permissions_access_area_check CHECK (scope IN ('calendar','pro_zone','plans_billing','lesson_pricing','google_calendar','stripe'));
CREATE OR REPLACE FUNCTION public.staff_access_coach(_user_id uuid, _scope text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT granted_by FROM public.staff_permissions WHERE user_id=_user_id AND scope=_scope AND public.has_role(_user_id,'staff') LIMIT 1 $$;
CREATE POLICY "Calendar staff manage granting coach lessons" ON public.lessons FOR ALL TO authenticated USING (coach_id=public.staff_access_coach(auth.uid(),'calendar')) WITH CHECK (coach_id=public.staff_access_coach(auth.uid(),'calendar'));
CREATE POLICY "Calendar staff manage granting coach recurring slots" ON public.recurring_lesson_slots FOR ALL TO authenticated USING (coach_id=public.staff_access_coach(auth.uid(),'calendar')) WITH CHECK (coach_id=public.staff_access_coach(auth.uid(),'calendar'));
CREATE POLICY "Calendar staff manage granting coach open slots" ON public.fixed_schedule_slots FOR ALL TO authenticated USING (coach_id=public.staff_access_coach(auth.uid(),'calendar')) WITH CHECK (coach_id=public.staff_access_coach(auth.uid(),'calendar'));
CREATE POLICY "Calendar staff read granting coach students" ON public.profiles FOR SELECT TO authenticated USING (assigned_coach_id=public.staff_access_coach(auth.uid(),'calendar'));
CREATE POLICY "Calendar staff read granting coach packages" ON public.class_packages FOR SELECT TO authenticated USING (coach_id=public.staff_access_coach(auth.uid(),'calendar'));
CREATE POLICY "Calendar staff read package members" ON public.package_members FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.class_packages cp WHERE cp.id=package_id AND cp.coach_id=public.staff_access_coach(auth.uid(),'calendar')));
CREATE POLICY "Calendar staff read student subscriptions" ON public.subscriptions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=student_id AND p.assigned_coach_id=public.staff_access_coach(auth.uid(),'calendar')));
CREATE POLICY "Calendar staff manage granting coach availability blocks" ON public.coach_availability_blocks FOR ALL TO authenticated USING (coach_id=public.staff_access_coach(auth.uid(),'calendar')) WITH CHECK (coach_id=public.staff_access_coach(auth.uid(),'calendar'));
CREATE POLICY "Scoped staff manage billing plans" ON public.billing_plans FOR ALL TO authenticated USING (public.has_staff_permission(auth.uid(),'plans_billing')) WITH CHECK (public.has_staff_permission(auth.uid(),'plans_billing'));
CREATE POLICY "Scoped staff manage granting coach pricing" ON public.coach_lesson_pricing FOR ALL TO authenticated USING (coach_id=public.staff_access_coach(auth.uid(),'lesson_pricing')) WITH CHECK (coach_id=public.staff_access_coach(auth.uid(),'lesson_pricing'));
CREATE POLICY "Scoped staff read relevant academy settings" ON public.academy_settings FOR SELECT TO authenticated USING ((key='google_calendar_sync' AND public.has_staff_permission(auth.uid(),'google_calendar')) OR (key IN ('lesson_types','lesson_pricing') AND public.has_staff_permission(auth.uid(),'lesson_pricing')));
CREATE POLICY "Scoped staff insert relevant academy settings" ON public.academy_settings FOR INSERT TO authenticated WITH CHECK ((key='google_calendar_sync' AND public.has_staff_permission(auth.uid(),'google_calendar')) OR (key='lesson_types' AND public.has_staff_permission(auth.uid(),'lesson_pricing')));
CREATE POLICY "Scoped staff update relevant academy settings" ON public.academy_settings FOR UPDATE TO authenticated USING ((key='google_calendar_sync' AND public.has_staff_permission(auth.uid(),'google_calendar')) OR (key='lesson_types' AND public.has_staff_permission(auth.uid(),'lesson_pricing'))) WITH CHECK ((key='google_calendar_sync' AND public.has_staff_permission(auth.uid(),'google_calendar')) OR (key='lesson_types' AND public.has_staff_permission(auth.uid(),'lesson_pricing')));
CREATE OR REPLACE FUNCTION public.staff_stripe_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_staff_permission(auth.uid(),'stripe')) THEN RAISE EXCEPTION 'Not authorized'; END IF; RETURN jsonb_build_object('total',(SELECT count(*) FROM public.stripe_payments),'latest',(SELECT jsonb_build_object('created_at',created_at,'status',status) FROM public.stripe_payments ORDER BY created_at DESC LIMIT 1)); END $$;
REVOKE ALL ON FUNCTION public.staff_stripe_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_stripe_status() TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.staff_access_coach(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_access_coach(uuid,text) TO authenticated,service_role;